#!/usr/bin/env bash
set -euo pipefail

# Orange Cat Investments (OCI) - Starter Platform Admin Credential Generator
# Generates a cryptographically secure, autogenerated bootstrap password
# and stores it in local gitignored credential files.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

CREDENTIALS_FILE="${REPO_ROOT}/starter-admin-credentials.txt"
CREDENTIALS_JSON="${REPO_ROOT}/.starter-admin-credentials.json"
FORCE=false

if [[ "${1:-}" == "--force" || "${1:-}" == "-f" ]]; then
    FORCE=true
fi

if [[ -f "${CREDENTIALS_FILE}" && "${FORCE}" == false ]]; then
    echo "================================================================================"
    echo "  Starter Admin Credentials Already Exist"
    echo "================================================================================"
    echo "Credential file: ${CREDENTIALS_FILE}"
    echo "Use --force to regenerate a new bootstrap password."
    echo "================================================================================"
    exit 0
fi

# Generate cryptographically secure password using Python secrets module (CSPRNG)
GENERATED_PASSWORD=$(python3 -c "
import secrets, string
uppercase = string.ascii_uppercase
lowercase = string.ascii_lowercase
digits = string.digits
symbols = '!@#$%^&*()-_=+[]{}'
all_chars = uppercase + lowercase + digits + symbols

while True:
    pwd = ''.join(secrets.choice(all_chars) for _ in range(24))
    if (sum(c in uppercase for c in pwd) >= 2 and
        sum(c in lowercase for c in pwd) >= 2 and
        sum(c in digits for c in pwd) >= 2 and
        sum(c in symbols for c in pwd) >= 2):
        print(pwd)
        break
")

# Set restrictive umask before creating credential files to avoid world-readable exposure
umask 077

cat <<EOF > "${CREDENTIALS_FILE}"
================================================================================
ORANGE CAT INVESTMENTS (OCI) - STARTER PLATFORM ADMINISTRATOR CREDENTIALS
================================================================================
Environment     : Production (oci-core)
Email / Login   : admin@oci.local
Employee ID     : 018f0000-0000-7000-8000-000000000001
Full Name       : Admin Officer
Role Title      : Platform Administrator & HR Lead
Role / Domain   : hr (Executive Workforce & Platform Administration)
Department      : Executive Operations
Initial Password: ${GENERATED_PASSWORD}
Generated At    : ${TIMESTAMP}

================================================================================
⚠️  CRITICAL SECURITY NOTICE - MANDATORY FIRST ACTION:
This starter administrator account is provisioned exclusively for initial platform
bootstrap in the production namespace (oci-core).

UPON FIRST LOGIN:
1. Log into the OCI Employee Portal (https://employee.oci.local) or Forgejo IdP.
2. CHANGE THIS PASSWORD IMMEDIATELY in platform account settings.
3. Begin onboarding permanent corporate staff, feline executives, and delegating
   least-privilege roles to team members.

File Location: starter-admin-credentials.txt (GITIGNORED - DO NOT COMMIT TO GIT)
================================================================================
EOF

cat <<EOF > "${CREDENTIALS_JSON}"
{
  "environment": "oci-core",
  "email": "admin@oci.local",
  "employee_id": "018f0000-0000-7000-8000-000000000001",
  "name": "Admin Officer",
  "role_title": "Platform Administrator & HR Lead",
  "role": "hr",
  "department": "Executive Operations",
  "initial_password": "${GENERATED_PASSWORD}",
  "generated_at": "${TIMESTAMP}",
  "security_notice": "Password MUST be changed immediately upon first login."
}
EOF

chmod 600 "${CREDENTIALS_FILE}" "${CREDENTIALS_JSON}"

# Provision Kubernetes secret if kubectl is configured
if command -v kubectl &>/dev/null; then
  if kubectl get namespace oci-internal &>/dev/null; then
    kubectl create secret generic starter-admin-credentials \
      --namespace oci-internal \
      --from-literal=ADMIN_USERNAME="admin" \
      --from-literal=ADMIN_EMAIL="admin@oci.local" \
      --from-literal=ADMIN_PASSWORD="${GENERATED_PASSWORD}" \
      --dry-run=client -o yaml | kubectl apply -f - >/dev/null 2>&1 || true
  fi
fi

echo "================================================================================"
echo "  ✅ Starter Platform Administrator Credentials Generated Successfully!"
echo "================================================================================"
echo "Account Email  : admin@oci.local"
echo "Employee ID    : 018f0000-0000-7000-8000-000000000001"
echo "Role           : hr (Platform Administrator & HR Lead)"
echo "Credentials at : ${CREDENTIALS_FILE}"
echo "JSON format at : ${CREDENTIALS_JSON}"
echo ""
echo "⚠️  MANDATORY ACTION: The generated password must be changed immediately upon first login!"
echo "================================================================================"
